	@Test
	void sameGroupFilterDiscountsPatternCostAndChangesJoinOrder() {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:plain> ?plain . ?s <urn:filtered> ?value . FILTER(?value > 1) }",
				null).getTupleExpr();

		new QueryJoinOptimizer(new EvaluationStatistics(), new EmptyTripleSource())
				.optimize(expression, null, EmptyBindingSet.getInstance());

		List<StatementPattern> patterns = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				patterns.add(pattern);
			}
		});
		StatementPattern filtered = patterns.stream()
				.filter(pattern -> "urn:filtered".equals(pattern.getPredicateVar().getValue().stringValue()))
				.findFirst()
				.orElseThrow();

		assertThat(filtered.getCostEstimate()).isCloseTo(52.5d * 0.8d, within(0.000001d));
		assertThat(patterns.getFirst()).isSameAs(filtered);
		assertThat(filtered.getResultSizeEstimate()).isEqualTo(100.0d);
	}

	@ParameterizedTest(name = "{0}")
	@MethodSource("filterGroups")
	void discountRespectsFilterReferencesAndGroupBoundaries(String label, String query, boolean discounted) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		StatementPattern pattern = findPattern(expression, "urn:target");
		PatternCostOptimizer optimizer = new PatternCostOptimizer();
		double cardinality = optimizer.getStatistics().getCardinality(pattern);

		assertThat(optimizer.patternCost(pattern)).as(label)
				.isEqualTo((cardinality + 5.0d) * (discounted ? 0.8d : 1.0d));
		assertThat(optimizer.getStatistics().getCardinality(pattern)).isEqualTo(cardinality);
	}

