	@Test
	void filterWrappedPatternReceivesOnlyOneDiscount() {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:plain> ?plain . { ?s <urn:target> ?value . "
						+ "FILTER(?value > 1) FILTER(?value < 10) } }",
				null).getTupleExpr();
		StatementPattern target = findPattern(expression, "urn:target");
		Filter factor = (Filter) target.getParentNode().getParentNode();

		new QueryJoinOptimizer(new EvaluationStatistics(), new EmptyTripleSource())
				.optimize(expression, null, EmptyBindingSet.getInstance());

		assertThat(factor.getCostEstimate()).isEqualTo(42.0d);
		assertThat(findFirstPattern(expression)).isSameAs(target);
	}

	@Test
	void joinEstimationPassRetainsTheFilterCostPreference() {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:plain> ?plain . ?s <urn:target> ?value . ?s <urn:other> ?other . "
						+ "FILTER(?value > 1) }",
				null).getTupleExpr();
		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public boolean supportsJoinEstimation() {
				return true;
			}

			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression instanceof Join join) {
					return isTarget(join.getLeftArg()) || isTarget(join.getRightArg()) ? 110.0d : 100.0d;
				}
				return super.getCardinality(expression);
			}

			private boolean isTarget(TupleExpr expression) {
				return expression instanceof StatementPattern pattern
						&& "urn:target".equals(pattern.getPredicateVar().getValue().stringValue());
			}
		};

		new QueryJoinOptimizer(statistics, new EmptyTripleSource())
				.optimize(expression, null, EmptyBindingSet.getInstance());

		assertThat(findFirstPattern(expression)).isSameAs(findPattern(expression, "urn:target"));
	}

