	@Test
	void structurallyEqualPatternsInDifferentGroupsHaveIndependentDiscounts() {
		StatementPattern filtered = new StatementPattern(Var.of("s"),
				Var.of("predicate", SimpleValueFactory.getInstance().createIRI("urn:target")), Var.of("value"));
		StatementPattern unfiltered = filtered.clone();
		new QueryRoot(new Union(new Filter(filtered, new Bound(Var.of("value"))),
				unfiltered));
		PatternCostOptimizer optimizer = new PatternCostOptimizer();

		assertThat(filtered).isEqualTo(unfiltered);
		assertThat(optimizer.patternCost(filtered)).isEqualTo(84.0d);
		assertThat(optimizer.patternCost(unfiltered)).isEqualTo(105.0d);
	}

	@Test
	void discountChangesOrderWithoutChangingTheQueryResultBag() throws Exception {
		SimpleValueFactory factory = SimpleValueFactory.getInstance();
		IRI first = factory.createIRI("urn:first");
		IRI second = factory.createIRI("urn:second");
		IRI plain = factory.createIRI("urn:plain");
		IRI target = factory.createIRI("urn:target");
		List<Statement> statements = List.of(
				factory.createStatement(first, plain, factory.createLiteral("excluded")),
				factory.createStatement(first, target, factory.createLiteral(1)),
				factory.createStatement(second, plain, factory.createLiteral("a")),
				factory.createStatement(second, plain, factory.createLiteral("b")),
				factory.createStatement(second, target, factory.createLiteral(2)));
		EmptyTripleSource source = new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(statements.stream()
						.filter(statement -> (subject == null || subject.equals(statement.getSubject()))
								&& (predicate == null || predicate.equals(statement.getPredicate()))
								&& (object == null || object.equals(statement.getObject())))
						.iterator());
			}
		};
		TupleExpr original = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:plain> ?plain . ?s <urn:target> ?value . FILTER(?value > 1) }", null)
				.getTupleExpr();
		TupleExpr optimized = original.clone();
		new QueryJoinOptimizer(new EvaluationStatistics(), source)
				.optimize(optimized, null, EmptyBindingSet.getInstance());

		List<BindingSet> expected = evaluate(original, source);
		assertThat(expected).hasSize(2);
		assertThat(evaluate(optimized, source)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(findFirstPattern(optimized)).isSameAs(findPattern(optimized, "urn:target"));
	}

	private static List<BindingSet> evaluate(TupleExpr expression, EmptyTripleSource source) throws Exception {
		List<BindingSet> results = new ArrayList<>();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		try (CloseableIteration<BindingSet> rows = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				results.add(rows.next());
			}
		}
		return results;
	}

	private static StatementPattern findFirstPattern(TupleExpr expression) {
		List<StatementPattern> patterns = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				patterns.add(pattern);
			}
		});
		return patterns.getFirst();
	}

	private static StatementPattern findPattern(TupleExpr expression, String predicate) {
		List<StatementPattern> patterns = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (predicate.equals(pattern.getPredicateVar().getValue().stringValue())) {
					patterns.add(pattern);
				}
			}
		});
		assertThat(patterns).hasSize(1);
		return patterns.getFirst();
	}

	private static class PatternCostOptimizer extends QueryJoinOptimizer {
		PatternCostOptimizer() {
			super(new EvaluationStatistics());
		}

		EvaluationStatistics getStatistics() {
			return statistics;
		}

		double patternCost(StatementPattern pattern) {
			return new PatternCostVisitor().cost(pattern);
		}

		private class PatternCostVisitor extends JoinVisitor {
			double cost(StatementPattern pattern) {
				List<Var> variables = pattern.getVarList();
				Map<Var, Integer> frequencies = new HashMap<>();
				fillVarFreqMap(variables, frequencies);
				return getTupleExprCost(pattern, Map.of(pattern, statistics.getCardinality(pattern)),
						Map.of(pattern, variables), frequencies);
			}
		}
	}
